documents.ranked:
yamaa: "1.0"
type: spec
domain: XX
keys: [STUDYID, USUBJID]
input:
  DM: input/dm.csv
  LB: {path: input/lb.csv, types: {LBSEQ: int, LBSTRESN: float}}
base: DM
output: {path: xx.csv, columns: [STUDYID, USUBJID, LASTSEQ, LASTRANK]}
intermediates:
  - id: LASTLB
    dataset: LB
    key: [STUDYID, USUBJID]
    order_by: [LB.LBSEQ]
    keep: last
    derivations:
      SORTV:
        case:
          - {when: "LB.LBSTRESN IS NULL", then: 0}
          - {otherwise: LB.LBSTRESN}
      RANKV: {row_number: {window: {group_by: [USUBJID], order_by: [SORTV]}}}
columns:
  - {name: STUDYID, type: str, derivation: DM.STUDYID}
  - {name: USUBJID, type: str, derivation: DM.USUBJID}
  - {name: LASTSEQ, type: int, derivation: LASTLB.LBSEQ}
  - {name: LASTRANK, type: int, derivation: LASTLB.RANKV}
